mapper.select:
select * from ( SELECT t.id_ id, t.process_Instant_Id_ processInstantId, t.biz_Id_ bizId, t.proc_Id_ procId, t.proc_Code_ procCode, t.proc_Name_ procName, t.proc_Version_ procVersion, t.module_Code_ moduleCode, t.module_Name_ moduleName, t.template_Code_ templateCode, t.template_Name_ templateName, t.process_Def_Id_ processDefId, t.process_Def_Key_ processDefKey, t.process_Def_Name_ processDefName, t.form_Code_ formCode, t.form_Name_ formName, t.task_Id_ taskId, t.task_Key_ taskKey, t.task_Name_ taskName, t.starter_Code_ starterCode, t.starter_Name_ starterName, t.starter_Unit_Code_ starterUnitCode, t.starter_Unit_Name_ starterUnitName, t.starter_Dept_Code_ starterDeptCode, t.starter_Dept_Name_ starterDeptName, t.start_Time_ startTime, t.end_Time_ endTime, t.duration_ duration, t.status_ STATUS, t.archieve_Time_ archieveTime, t.starter_Unit_Hierarchy_ starterUnitHierarchy FROM wf_his_proc_inst t, wf_proc_inst s, wf_his_proc_log l WHERE t.id_ = s.ID_ and (t.STATUS_ = '30' or t.STATUS_ = '40') and t.proc_Code_ in ('zybr_relGreat','zyzbyjybrel','zyzbyizdrel','zyzbejybrel','zyzbejzdrel') and t.process_Instant_Id_ = l.process_Instant_Id_ and l.task_name_ in ( '总部合规部门审核人','合规部门审核人') and l.action_ = 'COMPLETE'
and l.log_time_ like #{param.year}
and l.log_time_ >= #{param.beginQuarter}
and l.log_time_ < #{param.endQuarter}
and l.log_time_ >= #{param.startTime}
and l.log_time_ <= #{param.endTime}
order by t.created_time_ DESC )
